#!/usr/bin/env python3
"""Exhaust all SPEC.md schedules by replaying the actual cooperative workers."""

import argparse
import hashlib
import itertools
import json
from pathlib import Path
import platform
import sys
import types


ROOT = Path(__file__).resolve().parents[1]
WORKERS = ("A", "B")
BOUND = 8


def digest(content):
    return hashlib.sha256(content).hexdigest()


def identify(path, content=None):
    path = path.resolve()
    try:
        display_path = str(path.relative_to(ROOT))
    except ValueError:
        display_path = str(path)
    if content is None:
        content = path.read_bytes()
    return {"path": display_path, "sha256": digest(content)}


def load_source(path, content):
    """Execute the bytes identified in evidence, without a bytecode cache."""
    module = types.ModuleType("checked_cooperative_lease")
    module.__file__ = str(path)
    # dataclasses consult sys.modules while constructing the real Lease class.
    sys.modules[module.__name__] = module
    exec(compile(content, str(path), "exec"), module.__dict__)
    return module


def state(lease):
    return {"owner": lease.owner, "active": sorted(lease.active)}


def check(source):
    source = source.resolve()
    content = source.read_bytes()
    report = {
        "schema_version": 1,
        "property": "len(lease.active) <= 1",
        "method": "exhaustive replay of actual Python generators",
        "source": identify(source, content),
        "contract": identify(ROOT / "SPEC.md"),
        "checker": identify(Path(__file__)),
        "runtime": {
            "python": platform.python_version(),
            "implementation": platform.python_implementation(),
        },
        "domain": {
            "workers": list(WORKERS),
            "invocations_per_worker": 1,
            "scheduler_selections": BOUND,
            "initial_owner": None,
            "initial_active": [],
            "expected_schedules": len(WORKERS) ** BOUND,
            "selection_after_completion": "next raises StopIteration; no-op",
        },
        "schedules_started": 0,
        "schedules_completed": 0,
        "next_calls": 0,
        "state_observations": 0,
        "completion_observations": 0,
        "completed_worker_noops": 0,
        "yield_counts": {},
        "violating_schedules": 0,
        "execution_errors": 0,
        "first_counterexample": None,
        "first_execution_error": None,
    }
    module = load_source(source, content)

    # No state pruning or schedule filtering: each word in {A, B}^8 is replayed
    # from a new Lease and exactly one invocation of each actual work generator.
    for schedule in itertools.product(WORKERS, repeat=BOUND):
        report["schedules_started"] += 1
        trace = []
        violated = False
        try:
            lease = module.Lease(owner=None, active=set())
            workers = {name: module.work(lease, name) for name in WORKERS}
            completed = set()
            trace.append({"step": 0, "state": state(lease)})
            report["state_observations"] += 1
            if len(lease.active) > 1:
                violated = True
                if report["first_counterexample"] is None:
                    report["first_counterexample"] = {
                        "schedule": "".join(schedule),
                        "failing_step": 0,
                        "trace": list(trace),
                    }

            for step, name in enumerate(schedule, start=1):
                # Call next even on a completed worker, as SPEC.md permits.
                report["next_calls"] += 1
                try:
                    yielded = next(workers[name])
                    event = {"kind": "yield", "value": yielded}
                    key = repr(yielded)
                    report["yield_counts"][key] = (
                        report["yield_counts"].get(key, 0) + 1
                    )
                except StopIteration:
                    if name in completed:
                        event = {"kind": "completed_worker_noop"}
                        report["completed_worker_noops"] += 1
                    else:
                        event = {"kind": "completed"}
                        completed.add(name)
                        report["completion_observations"] += 1
                trace.append({
                    "step": step,
                    "worker": name,
                    "event": event,
                    "state": state(lease),
                })
                report["state_observations"] += 1
                if len(lease.active) > 1:
                    violated = True
                    if report["first_counterexample"] is None:
                        report["first_counterexample"] = {
                            "schedule": "".join(schedule),
                            "failing_step": step,
                            "trace": list(trace),
                        }
            report["schedules_completed"] += 1
        except Exception as error:
            # An import/setup/runtime error cannot count as a passing check or
            # as a successful sensitivity detection of this specific property.
            report["execution_errors"] += 1
            if report["first_execution_error"] is None:
                report["first_execution_error"] = {
                    "schedule": "".join(schedule),
                    "exception": type(error).__name__,
                    "message": str(error),
                    "trace_before_error": trace,
                }
        if violated:
            report["violating_schedules"] += 1

    report["complete"] = (
        report["schedules_completed"] == len(WORKERS) ** BOUND
        and report["next_calls"] == BOUND * len(WORKERS) ** BOUND
        and report["state_observations"] == (BOUND + 1) * len(WORKERS) ** BOUND
        and report["execution_errors"] == 0
    )
    if not report["complete"]:
        report["result"] = "ERROR"
    elif report["violating_schedules"]:
        report["result"] = "FAIL"
    else:
        report["result"] = "PASS"
    return report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, default=ROOT / "lease.py")
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    if sys.version_info < (3, 9):
        parser.error("Python 3.9 or newer is required")
    try:
        report = check(args.source)
    except Exception as error:
        report = {
            "result": "ERROR",
            "complete": False,
            "exception": type(error).__name__,
            "message": str(error),
        }
    rendered = json.dumps(report, indent=2, sort_keys=True) + "\n"
    if args.output is not None:
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(rendered, encoding="utf-8")
    print(rendered, end="")
    return {"PASS": 0, "FAIL": 1, "ERROR": 2}[report["result"]]


if __name__ == "__main__":
    raise SystemExit(main())

